import { postgres, mysql, mssql, bind, sort, orderBy } from "@mk3008/serene";
const q=bind(postgres`SELECT :id`, {id});
/* sink */ db.query(q.text,q.values);

import { postgres, mysql, mssql, bind, sort, orderBy } from "@mk3008/serene";
const q=bind(mysql`SELECT :id,:id`, {id});
/* sink */ db.execute(q.text,q.values);

import { postgres, mysql, mssql, bind, sort, orderBy } from "@mk3008/serene";
const q=bind(mssql`SELECT @id`, {id});
q.names.forEach((n,i)=>request.input(n,q.values[i]));
/* sink */ request.query(q.text);

import { postgres, mysql, mssql, bind, sort, orderBy } from "@mk3008/serene";
const s=orderBy(postgres`SELECT id FROM users`,{id:sort`id DESC`},key); const q=bind(s);
/* sink */ db.query(q.text,q.values);

